{"operationName":"GetFooter","variables":{"pageTitle":"Footer"},"query":"query GetFooter($pageTitle: String!) {
  footer: footerLayoutCollection(limit: 1, where: {title: $pageTitle}) {
    items {
      footerLinksCollection(limit: 10) {
        items {
          ... on Footer {
            footerId
            footerName
            footerLink
            __typename
          }
          __typename
        }
        __typename
      }
      copyRights
      socialMediaIconsCollection(limit: 10) {
        items {
          ... on SocialIcon {
            name
            altText
            url
            footerIcon {
              url
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}"}

